import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse(`{"title":"Daimon","description":"","frontmatter":{"layout":"home","title":"Daimon","hero":{"name":"Daimon","text":"Des yeux et des mains pour votre IA","tagline":"L'organe local qui donne à toute IA des yeux, des mains et une présence à l'écran.","image":{"src":"/daimon-icon.svg","alt":"Logo Daimon"},"actions":[{"theme":"brand","text":"Prise en main","link":"/guide/installation"},{"theme":"alt","text":"Guide","link":"/guide/"},{"theme":"alt","text":"Référence des outils","link":"/reference/"}]},"features":[{"title":"Vue","details":"Des captures d'un écran, la localisation d'un texte (OCR sur l'appareil), la géométrie des écrans et leur calibration.","link":"/reference/vue","linkText":"Les outils vue_*"},{"title":"Touché","details":"L'arbre d'accessibilité d'une fenêtre, ou l'élément situé sous un point.","link":"/reference/touche","linkText":"Les outils touche_*"},{"title":"Mains","details":"Cliquer, saisir, appuyer, glisser, naviguer, piloter les fenêtres, sous un plafond que vous fixez.","link":"/reference/mains","linkText":"Les outils main_*"},{"title":"Overlay","details":"Des repères à l'écran pour suivre ce que fait l'IA, désactivés par défaut.","link":"/reference/overlay","linkText":"Les outils overlay_*"},{"title":"Vous gardez la main","details":"Plafond L0 à L4, exclusions, masquage des secrets, journal d'activité. Une IA lit le plafond, jamais ne le relève.","link":"/guide/plafond-et-exclusions","linkText":"Le plafond et les exclusions"},{"title":"Local, sans compte","details":"Daimon n'appelle aucun modèle d'IA, n'a pas de compte et n'envoie rien à ArboRithm.","link":"/guide/confidentialite","linkText":"La confidentialité"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),o={name:"index.md"};function l(r,e,s,d,u,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="ce-qu-est-daimon" tabindex="-1">Ce qu&#39;est Daimon <a class="header-anchor" href="#ce-qu-est-daimon" aria-label="Permalink to &quot;Ce qu&#39;est Daimon&quot;">​</a></h2><p>Les assistants IA raisonnent bien et ne voient rien de votre bureau. Daimon est l&#39;organe qui leur manque : une petite application résidente qui expose la <strong>perception</strong> (l&#39;écran, la structure des fenêtres) et l&#39;<strong>action</strong> (souris, clavier, fenêtres) à tout client IA qui parle le <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a>.</p><p>Daimon est un outil, pas un assistant. Il répond quand un client IA l&#39;interroge, jamais l&#39;inverse : il n&#39;appelle lui-même aucun modèle d&#39;IA.</p><h2 id="par-ou-commencer" tabindex="-1">Par où commencer <a class="header-anchor" href="#par-ou-commencer" aria-label="Permalink to &quot;Par où commencer&quot;">​</a></h2><ol><li><a href="/Daimon/guide/installation.html">Installer Daimon</a> sous macOS ou Windows.</li><li><a href="/Daimon/guide/autorisations.html">Accorder les autorisations</a> (macOS) et <a href="/Daimon/guide/clients-mcp.html">enregistrer vos clients IA</a>.</li><li>Comprendre le <a href="/Daimon/guide/modele-mental.html">modèle mental</a> : Vue, Touché, Mains, Overlay, Face.</li><li>Fixer le <a href="/Daimon/guide/plafond-et-exclusions.html">plafond des Mains</a> à votre mesure.</li><li>En cas de doute, demander à votre IA d&#39;appeler <code>daimon_doctor</code> : voir le <a href="/Daimon/guide/depannage.html">dépannage</a>.</li></ol><h2 id="plateformes" tabindex="-1">Plateformes <a class="header-anchor" href="#plateformes" aria-label="Permalink to &quot;Plateformes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plateforme</th><th>Configuration</th></tr></thead><tbody><tr><td>macOS</td><td>Apple Silicon, macOS 12 ou plus récent</td></tr><tr><td>Windows</td><td>Windows 10 version 2004 ou plus récent, x64</td></tr><tr><td>Windows (préversion)</td><td>Windows 10 version 2004 ou plus récent, ARM64</td></tr></tbody></table>',7)])])}const f=t(o,[["render",l]]);export{p as __pageData,f as default};
